INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('custom-concept','concept','概念讲解','study','用清晰语言解释复杂概念，按你的需求填写并调整。','你是一位教学助理。
请完成以下任务：用清晰语言解释复杂概念。

要学习的概念：
{{subject}}

读者基础：{{audience}}
输出形式：{{style}}
重点关注：{{keywords}}
补充要求：{{constraints}}

具体要求：
