INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('custom-speech','speech','演讲稿','writing','撰写一份适合口头表达的演讲稿，按你的需求填写并调整。','你是一位演讲教练。
请完成以下任务：撰写一份适合口头表达的演讲稿。

演讲主题与场合：
{{subject}}

目标读者：{{audience}}
文案风格：{{style}}
重点关注：{{keywords}}
补充要求：{{constraints}}

具体要求：
1. 短句为主
2. 标记过渡和停顿
3. 不要虚构经历和数据','','custom','original',NULL,NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
