DELETE FROM template_fields WHERE template_id='aishort-2';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-3','aishort-3','语音输入优化','writing','先用第三方应用将语音转换成文字，再用 ChatGPT 进行处理。在进行语音录入时，通常会习惯性地说一些口头禅和语气词，使用 ChatGPT 可以将其转换成书面语言，以优化语音转文字的效果。此外，它还可以用于整理无序文本。源于 @玉树芝兰老师的「用简洁的语言整理这一段话，要逻辑清晰，去掉错别字」。','Using concise and clear language, please edit the following passage to improve its logical flow, eliminate any typographical errors. Be sure to maintain the original meaning of the text. Respond in Chinese. Please begin by editing the following text: [语音文字输入]','请用简洁明了的语言，编辑以下段落，以改善其逻辑流程，消除任何印刷错误，并以中文作答。请务必保持文章的原意。请从编辑以下文字开始：[语音文字输入]','imported','aishort','3',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-3';
