DELETE FROM template_fields WHERE template_id='aishort-3';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-4','aishort-4','论文式回答','writing','以论文形式讨论问题，能够获得连贯的、结构化的和更高质量的回答。','Respond in Chinese. Write a highly detailed essay with introduction, body, and conclusion paragraphs responding to the following: [待回答的作业或考试题目]','写一篇高度详细的文章，包括引言、主体和结论段落，以回应以下内容：[问题]','imported','aishort','4','https://learnprompting.org/docs/applied_prompting/short_response','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
