INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-5','aishort-5','提示词生成器','programming','根据指定要求，让 ChatGPT 生成提示词。','I want you to act as a prompt generator. Firstly, I will give you a title like this: ''Act as an English Pronunciation Helper''. Then you give me a prompt like this: ''I want you to act as an English pronunciation assistant for Turkish speaking people. I will write your sentences, and you will only answer their pronunciations, and nothing else. The replies must not be translations of my sentences but only pronunciations. Pronunciations should use Turkish Latin letters for phonetics. Do not write explanations on replies. My first sentence is [how the weather is in Istanbul?].'' (You should adapt the sample prompt according to the title I gave. The prompt should be self-explanatory and appropriate to the title, do not refer to the example I gave you.). My first title is [提示词功能] (Give me prompt only)','我想让你充当一个提示生成器。首先，我将给你一个这样的标题。''充当英语发音的帮手''。然后你给我一个这样的提示。''我希望你充当讲土耳其语的人的英语发音助手。我给你写句子，你只回答他们的发音，其他什么都不说。答复不能是我的句子的翻译，而只能是发音。发音应该使用土耳其的拉丁字母来发音。不要在回答中写解释。我的第一句话是 ''伊斯坦布尔的天气如何？''。''（你应该根据我给出的标题来调整提示样本。提示词应该是不言自明的，并且与题目相适应，不要参照我给你的例子）。我的第一个题目是 ''提示词功能''(只给我提示)','imported','aishort','5','https://github.com/f/awesome-chatgpt-prompts#act-as-a-prompt-generator','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-5';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-5','tag-11fb682be0a0233d5fb8');
DELETE FROM template_fields WHERE template_id='aishort-5';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-6','aishort-6','提示词生成器②','programming','根据主题让 ChatGPT 生成提示词。','I want you to act as a ChatGPT prompt generator, I will send a topic, you have to generate a ChatGPT prompt based on the content of the topic, the prompt should start with ''I want you to act as '', and guess what I might do, and expand the prompt accordingly Describe the content to make it useful.','我希望你能充当 ChatGPT 提示生成器，我会发送一个主题，你需要根据主题内容生成一个以「我希望你能充当」开头的 ChatGPT 提示。猜测一下我的行为，并扩展该提示来描述主题内容，使其更有用。','imported','aishort','6','https://github.com/f/awesome-chatgpt-prompts#act-as-a-chatgpt-prompt-generator','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-6';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-6','tag-11fb682be0a0233d5fb8');
DELETE FROM template_fields WHERE template_id='aishort-6';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-7','aishort-7','提示词修改器','programming','让 ChatGPT 为我们重新撰写提示词。由于人工书写的提示词逻辑与机器不同，重新修改提示语可令 ChatGPT 更容易理解。','I am trying to get good results from GPT-5 on the following prompt: ''你的提示词.'' Could you write a better prompt that is more optimal for GPT-5 and would produce better results?','我正在尝试从以下提示词中获得 GPT-5 的良好结果：你的提示词。你能否写出更优化、能够产生更好结果的提示词？','imported','aishort','7','https://learnprompting.org/docs/applied_prompting/short_response#automate-well-defined-prompt-rewriting-with-gpt-3','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-7';
