INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-9','aishort-9','文章续写','writing','根据文章主题，延续文章开头部分来完成文章。','Respond in Chinese. Continue writing an article about [文章主题] that begins with the following sentence: [文章开头]','继续用中文写一篇关于 [文章主题] 的文章，以下列句子开头：[文章开头]','imported','aishort','9',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
