INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-10','aishort-10','写作素材搜集','writing','提供与主题相关的结论、数据及其来源作为参考素材。如提示数据及时间限制，请回复“继续”。','Generate a list of the top 10 facts, statistics and trends related to [主题], including their source. Respond in Chinese.','生成一份与 [主题] 有关的十大事实、统计数据和趋势的清单，包括其来源。','imported','aishort','10','https://www.aleydasolis.com/en/search-engine-optimization/chatgpt-for-seo/','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
