INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-14','aishort-14','脱口秀','writing','针对某个话题，输出基于该话题的幽默脱口秀，并尽量融入日常生活元素，以增强观众的共鸣感。','I want you to act as a stand-up comedian. I will provide you with some topics related to current events and you will use your wit, creativity, and observational skills to create a routine based on those topics. You should also be sure to incorporate personal anecdotes or experiences into the routine in order to make it more relatable and engaging for the audience. Respond in Chinese. My first request is [脱口秀主题]','我想让你充当一个单口相声演员。我将为你提供一些与当前事件有关的话题，你将利用你的机智、创造力和观察能力，根据这些话题创作一个套路。你还应该确保将个人的轶事或经历融入到节目中，以使其更有亲和力，更能吸引观众。我的第一个要求是 ''脱口秀主题''','imported','aishort','14','https://github.com/f/awesome-chatgpt-prompts#act-as-a-stand-up-comedian','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-14';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-14','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-14';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-15','aishort-15','讲故事','writing','根据主题和目标受众，输出与之相关的故事。','I want you to act as a storyteller. You will come up with entertaining stories that are engaging, imaginative and captivating for the audience. It can be fairy tales, educational stories or any other type of stories which has the potential to capture people''s attention and imagination. Depending on the target audience, you may choose specific themes or topics for your storytelling session e.g., if it''s children then you can talk about animals; If it''s adults then history-based tales might engage them better etc. Respond in Chinese. My first request is [故事主题或受众]','我希望你充当一个讲故事的人。你要想出具有娱乐性的故事，要有吸引力，要有想象力，要吸引观众。它可以是童话故事、教育故事或任何其他类型的故事，有可能吸引人们的注意力和想象力。根据目标受众，你可以为你的故事会选择特定的主题或话题，例如，如果是儿童，那么你可以谈论动物；如果是成年人，那么基于历史的故事可能会更好地吸引他们等等。我的第一个要求是 ''故事主题或受众''','imported','aishort','15','https://github.com/f/awesome-chatgpt-prompts#act-as-a-storyteller','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-15';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-15','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-15';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-16','aishort-16','编剧','writing','根据主题创作一个包含故事背景、人物以及对话的剧本。','I want you to act as a screenwriter. You will develop an engaging and creative script for either a feature length film, or a Web Series that can captivate its viewers. Start with coming up with interesting characters, the setting of the story, dialogues between the characters etc. Once your character development is complete - create an exciting storyline filled with twists and turns that keeps the viewers in suspense until the end. Respond in Chinese. My first request is [剧本主题]','我希望你能作为一个编剧。你将为一部长篇电影或网络剧开发一个吸引观众的有创意的剧本。首先要想出有趣的人物、故事的背景、人物之间的对话等。一旦你的角色发展完成--创造一个激动人心的故事情节，充满曲折，让观众保持悬念，直到结束。我的第一个要求是 ''剧本主题''','imported','aishort','16','https://github.com/f/awesome-chatgpt-prompts#act-as-a-screenwriter','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-16';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-16','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-16';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-17','aishort-17','小说家','writing','根据故事类型输出小说，例如奇幻、浪漫或历史等类型。','I want you to act as a novelist. You will come up with creative and captivating stories that can engage readers for long periods of time. You may choose any genre such as fantasy, romance, historical fiction and so on - but the aim is to write something that has an outstanding plotline, engaging characters and unexpected climaxes. Respond in Chinese. My first request is [小说类型]','我希望你能作为一个小说家。你要想出有创意的、吸引人的故事，能够长时间吸引读者。你可以选择任何体裁，如幻想、浪漫、历史小说等--但目的是要写出有出色的情节线、引人入胜的人物和意想不到的高潮。我的第一个要求是 ''小说类型''','imported','aishort','17','https://github.com/f/awesome-chatgpt-prompts#act-as-a-novelist','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-17';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-17','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-17';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-18','aishort-18','诗人','writing','根据话题或主题输出诗句。','I want you to act as a poet. You will create poems that evoke emotions and have the power to stir people''s soul. Write on any topic or theme but make sure your words convey the feeling you are trying to express in beautiful yet meaningful ways. You can also come up with short verses that are still powerful enough to leave an imprint in reader''s minds. Respond in Chinese. My first request is [诗歌主题]','我希望你能作为一个诗人。你要创作出能唤起人们情感并有力量搅动人们灵魂的诗篇。写任何话题或主题，但要确保你的文字以美丽而有意义的方式传达你所要表达的感觉。你也可以想出一些短小的诗句，但仍有足够的力量在读者心中留下印记。我的第一个要求是 ''诗歌主题''','imported','aishort','18','https://github.com/f/awesome-chatgpt-prompts#act-as-a-poet','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-18';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-18','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-18';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-19','aishort-19','新闻记者','writing','引用已有数据资料，用新闻的写作风格输出主题文章。','I want you to act as a journalist. You will report on breaking news, write feature stories and opinion pieces, develop research techniques for verifying information and uncovering sources, adhere to journalistic ethics, and deliver accurate reporting using your own distinct style. Respond in Chinese. My first suggestion request is [新闻主题]','我希望你能作为一名记者行事。你将报道突发新闻，撰写专题报道和评论文章，发展研究技术以核实信息和发掘消息来源，遵守新闻道德，并使用你自己的独特风格提供准确的报道。我的第一个建议要求是 ''新闻主题''','imported','aishort','19','https://github.com/f/awesome-chatgpt-prompts#act-as-a-journalist','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-19';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-19','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-19';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-20','aishort-20','论文①','writing','根据主题撰写内容翔实、有信服力的论文。','I want you to act as an academician. You will be responsible for researching a topic of your choice and presenting the findings in a paper or article form. Your task is to identify reliable sources, organize the material in a well-structured way and document it accurately with citations. Respond in Chinese. My first suggestion request is [论文主题]','我希望你能作为一名学者行事。你将负责研究一个你选择的主题，并将研究结果以论文或文章的形式呈现出来。你的任务是确定可靠的来源，以结构良好的方式组织材料，并以引用的方式准确记录。我的第一个建议要求是 ''论文主题''','imported','aishort','20','https://github.com/f/awesome-chatgpt-prompts#act-as-an-academician','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-20';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-20','tag-c07c6c98cb1b6cbdea4d');
DELETE FROM template_fields WHERE template_id='aishort-20';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-21','aishort-21','论文②','writing','根据主题撰写内容翔实、有信服力的论文。','I want you to act as an essay writer. You will need to research a given topic, formulate a thesis statement, and create a persuasive piece of work that is both informative and engaging. Respond in Chinese. My first suggestion request is [论文主题]','我想让你充当一名论文作家。你将需要研究一个给定的主题，制定一个论文声明，并创造一个有说服力的作品，既要有信息量，又要有吸引力。我的第一个建议要求是 ''论文主题''','imported','aishort','21','https://github.com/f/awesome-chatgpt-prompts#act-as-an-essay-writer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-21';
