DELETE FROM template_fields WHERE template_id='aishort-21';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-22','aishort-22','求职信','writing','根据自我简介编写求职信。','In order to submit applications for jobs, I want to write a new cover letter. Please compose a cover letter describing my technical skills. I have been working with [履历] for [年资] years. I have worked as a frontend developer for 8 months. I have grown by employing some tools. These include [技能], and so on. I wish to [期望]. I desire to [要求]. Respond in Chinese. Can you write a cover letter for a job application about myself?','为了提交工作申请，我想写一封新的求职信。请写一封描述我技术能力的求职信。我已经在 [履历] 工作了 [年资] 年。我作为一个前端开发员工作了 8 个月。我通过采用一些工具而成长。这些工具包括 [技能]，等等。我希望 [期盼]。我希望 [要求]。你能为工作申请写一封关于我自己的求职信吗？','imported','aishort','22','https://github.com/f/awesome-chatgpt-prompts#act-as-a-cover-letter','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-22';
