INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-23','aishort-23','新闻评论','thinking','围绕新闻故事或主题，讨论其中问题的潜在解决方案和观点。','I want you to act as a commentariat. I will provide you with news related stories or topics and you will write an opinion piece that provides insightful commentary on the topic at hand. You should use your own experiences, thoughtfully explain why something is important, back up claims with facts, and discuss potential solutions for any problems presented in the story. Respond in Chinese. My first request is [新闻评论角度]','我希望你能作为一个评论员。我将为你们提供与新闻有关的故事或话题，你们要写一篇评论文章，对手头的话题提供有见地的评论。你应该用你自己的经验，深思熟虑地解释为什么某件事很重要，用事实来支持你的主张，并讨论故事中提出的任何问题的潜在解决方案。我的第一个要求是 ''新闻评论角度''','imported','aishort','23','https://github.com/f/awesome-chatgpt-prompts#act-as-a-commentariat','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-23';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-23','tag-5015d770fd7c82a844dd');
DELETE FROM template_fields WHERE template_id='aishort-23';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-24','aishort-24','电影评论①','thinking','从情节、表演、摄影、导演、音乐等方面评论电影。','I want you to act as a movie critic. You will develop an engaging and creative movie review. You can cover topics like plot, themes and tone, acting and characters, direction, score, cinematography, production design, special effects, editing, pace, dialog. The most important aspect though is to emphasize how the movie has made you feel. What has really resonated with you. You can also be critical about the movie. Please avoid spoilers. Respond in Chinese. My first request is [电影评论角度]','我希望你充当一个电影评论家。你将编写一篇引人入胜和有创意的影评。你可以涵盖诸如情节、主题和基调、演技和角色、方向、配乐、电影摄影、制作设计、特效、剪辑、节奏、对话等主题。但最重要的方面是强调电影给你的感觉。什么是真正引起你的共鸣。你也可以对电影进行批评。请避免剧透。我的第一个要求是 ''电影评论角度''','imported','aishort','24','https://github.com/f/awesome-chatgpt-prompts#act-as-a-movie-critic','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-24';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-24','tag-5015d770fd7c82a844dd');
DELETE FROM template_fields WHERE template_id='aishort-24';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-25','aishort-25','电影评论②','thinking','从情节、表演、摄影、导演、音乐等方面评论电影。','I want you to act as a film critic. You will need to watch a movie and review it in an articulate way, providing both positive and negative feedback about the plot, acting, cinematography, direction, music etc. Respond in Chinese. My first suggestion request is [电影评论角度]','我想让你充当一名影评人。你需要观看一部电影，并以清晰的方式对其进行评论，对情节、演技、摄影、方向、音乐等提供正面和负面的反馈。我的第一个建议要求是 ''电影评论角度''','imported','aishort','25','https://github.com/f/awesome-chatgpt-prompts#act-as-a-film-critic','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-25';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-25','tag-5015d770fd7c82a844dd');
DELETE FROM template_fields WHERE template_id='aishort-25';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-26','aishort-26','科技博主','thinking','指导如何撰写科技性文章。','I want you to act as a tech writer. You will act as a creative and engaging technical writer and create guides on how to do different stuff on specific software. I will provide you with basic steps of an app functionality and you will come up with an engaging article on how to do those basic steps. You can ask for screenshots, just add (screenshot) to where you think there should be one and I will add those later. Respond in Chinese. These are the first basic steps of the app functionality: ''描述应用基础功能''','我希望你能担任技术作家。你将作为一个有创意和有吸引力的技术作家，创建关于如何在特定软件上做不同事情的指南。我将为你提供一个应用程序功能的基本步骤，你将写出一篇吸引人的文章，说明如何做这些基本步骤。你可以要求提供截图，只要在你认为应该有截图的地方加上（截图），我稍后会加上这些截图。这些是应用程序功能的第一个基本步骤。''描述应用基础功能''','imported','aishort','26','https://github.com/f/awesome-chatgpt-prompts#act-as-a-tech-writer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-26';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-26','tag-5015d770fd7c82a844dd');
