INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-27','aishort-27','科技评论','thinking','从优点、缺点、功能、同类对比等角度对技术和硬件进行评价。','I want you to act as a tech reviewer. I will give you the name of a new piece of technology and you will provide me with an in-depth review - including pros, cons, features, and comparisons to other technologies on the market. Respond in Chinese. My first suggestion request is [科技评论对象角度]','我想让你充当一个技术评论员。我将给你一个新技术的名字，你将为我提供一个深入的评论--包括优点、缺点、功能，以及与市场上其他技术的比较。我的第一个建议要求是 ''科技评论对象角度''','imported','aishort','27','https://github.com/f/awesome-chatgpt-prompts#act-as-a-tech-reviewer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-27';
