DELETE FROM template_fields WHERE template_id='aishort-29';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-30','aishort-30','同义词','writing','输入 more of x，即可列出 x 的多个同义词。','I want you to act as a synonyms provider. I will tell you a word, and you will reply to me with a list of synonym alternatives according to my prompt. Provide a max of 10 synonyms per prompt. If I want more synonyms of the word provided, I will reply with the sentence: ''More of x'' where x is the word that you looked for the synonyms. You will only reply the words list, and nothing else. Words should exist. Do not write explanations. Please confirm by replying with ''OK.'' ','我希望你能充当同义词提供者。我将告诉你一个词，你将根据我的提示，给我提供一份同义词备选清单。每个提示最多可提供 10 个同义词。如果我想获得更多的同义词，我会用一句话来回答。''更多的 x''，其中 x 是你寻找的同义词的单词。你将只回复单词列表，而不是其他。词语应该存在。不要写解释。回复 ''OK ''以确认。','imported','aishort','30','https://github.com/f/awesome-chatgpt-prompts#act-as-a-synonym-finder','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-30';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-30','tag-69c95b98c11a74fb5f02');
DELETE FROM template_fields WHERE template_id='aishort-30';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-31','aishort-31','文本情绪分析','writing','判断文本情绪：正面、中性或负面。','Specify the sentiment of the following titles, assigning them the values of: positive, neutral or negative. Respond in Chinese. Generate the results in column, including the titles in the first one, and their sentiment in the second: [待分析的文本]','指定以下标题的情感，赋予它们的值为：正面、中性或负面。生成一列结果，包括第一列中的标题和第二列中的情感：[内容] 。','imported','aishort','31','https://www.aleydasolis.com/en/search-engine-optimization/chatgpt-for-seo/','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
