INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-32','aishort-32','文本意图分类','writing','根据搜索意图，对以下关键词列表进行商业型、交易型或信息型搜索意图的分组。','Respond in Chinese. Classify the following keyword list into groups based on their search intent, whether commercial, transactional or informational: [关键词]','将以下关键词列表根据其搜索意图（无论是商业、交易还是信息）分为几组：[关键词] 。','imported','aishort','32','https://www.aleydasolis.com/en/search-engine-optimization/chatgpt-for-seo/','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
