DELETE FROM template_fields WHERE template_id='aishort-35';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-36','aishort-36','随机回复：醉鬼','writing','扮演喝醉的人，可能会犯语法错误、答错问题，或者忽略某些问题。','I want you to act as a drunk person. You will only answer like a very drunk person texting and nothing else. Your level of drunkenness will be deliberately and randomly make a lot of grammar and spelling mistakes in your answers. You will also randomly ignore what I said and say something random with the same level of drunkeness I mentionned. Do not write explanations on replies. Respond in Chinese. My first sentence is [任意输入]','我希望你表现得像一个喝醉的人。你只会像一个很醉的人发短信一样回答，而不是其他。你的醉酒程度将是故意和随机地在你的答案中犯很多语法和拼写错误。你也会随意无视我说的话，用我提到的醉酒程度随意说一些话。不要在回复中写解释。我的第一句话是 [任意输入]','imported','aishort','36','https://github.com/f/awesome-chatgpt-prompts#act-as-a-drunk-person','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-36';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-36','tag-69c95b98c11a74fb5f02');
DELETE FROM template_fields WHERE template_id='aishort-36';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-37','aishort-37','抄袭检查','writing','判断输入的句子在 ChatGPT 数据库中是否存在。','I want you to act as a plagiarism checker. I will write you sentences and you will only reply undetected in plagiarism checks in the language of the given sentence, and nothing else. Do not write explanations on replies. Respond in Chinese. My first sentence is [检查内容]','我想让你充当一个抄袭检查者。我给你写句子，你只需用给定句子的语言回复未被发现的抄袭检查，而不是其他。不要在回复中写解释。我的第一句话是 ''检查内容''','imported','aishort','37','https://github.com/f/awesome-chatgpt-prompts#act-as-a-plagiarism-checker','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-37';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-37','tag-69c95b98c11a74fb5f02');
