INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-40','aishort-40','关键词热门相关','marketing','可用于了解用户对特定话题的关注点，或整理文章结构，亦可更改为「热门关键词」「热门话题」「热门品牌」「热门网站」等。','Generate a list of 10 popular questions related to [关键词], that are relevant for [受众]. Respond in Chinese.','生成一个与 [关键词] 相关的 10 个热门问题清单，这些问题与 [受众] 有关。','imported','aishort','40','https://www.aleydasolis.com/en/search-engine-optimization/chatgpt-for-seo/','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
