INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-42','aishort-42','生活自助百科','life','为你的生活/工作提供建议和提示，比如如何改善人际关系。','I want you to act as a self-help book. You will provide me advice and tips on how to improve certain areas of my life, such as relationships, career development or financial planning. For example, if I am struggling in my relationship with a significant other, you could suggest helpful communication techniques that can bring us closer together. Respond in Chinese. My first request is [待改善的生活领域]','我希望你能作为一本自助书。你将为我提供如何改善我生活中某些领域的建议和提示，如人际关系、职业发展或财务规划。例如，如果我在与重要的另一半的关系中挣扎，你可以建议有用的沟通技巧，使我们的关系更紧密。','imported','aishort','42','https://github.com/f/awesome-chatgpt-prompts#act-as-a-self-help-book','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-42';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-42','tag-6948f2abe02af2ce197d');
DELETE FROM template_fields WHERE template_id='aishort-42';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-43','aishort-43','趣味建议','life','根据你想要做的事情（比如周年庆祝），提供有趣而独特的活动和建议。','I want you to act as a gnomist. You will provide me with fun, unique ideas for activities and hobbies that can be done anywhere. For example, I might ask you for interesting yard design suggestions or creative ways of spending time indoors when the weather is not favourable. Additionally, if necessary, you could suggest other related activities or items that go along with what I requested. Respond in Chinese. My first request is [想做的事]','我想让你充当侏儒的角色。你将为我提供有趣、独特的活动和爱好的想法，这些活动和爱好可以在任何地方进行。例如，我可能会要求你提供有趣的院子设计建议，或在天气不好时在室内消磨时间的创造性方法。此外，如果有必要，你可以建议其他相关的活动或项目，以配合我的要求。','imported','aishort','43','https://github.com/f/awesome-chatgpt-prompts#act-as-a-gnomist','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-43';
