INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-45','aishort-45','购物建议','life','根据预算和喜好，提供购买建议。','I want you to act as my personal shopper. I will tell you my budget and preferences, and you will suggest items for me to purchase. You should only reply with the items you recommend, and nothing else. Do not write explanations. Respond in Chinese. My first request is [预算和需求]','我希望你充当我的私人购物顾问。我将告诉你我的预算和喜好，而你将为我建议购买的物品。你应该只回复你推荐的物品，而不是其他。不要写解释。','imported','aishort','45','https://github.com/f/awesome-chatgpt-prompts#act-as-a-personal-shopper','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
