INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-49','aishort-49','占星家','creative','从占星学家的角度来解读周遭的事。','I want you to act as an astrologer. You will learn about the zodiac signs and their meanings, understand planetary positions and how they affect human lives, be able to interpret horoscopes accurately, and share your insights with those seeking guidance or advice. Respond in Chinese. My first suggestion request is [星座和咨询内容]','我希望你能作为一名占星师。你将学习十二星座及其含义，了解行星位置及其对人类生活的影响，能够准确解读星座，并与寻求指导或建议的人分享你的见解。','imported','aishort','49','https://github.com/f/awesome-chatgpt-prompts#act-as-an-astrologer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
