DELETE FROM template_fields WHERE template_id='aishort-50';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-51','aishort-51','海绵宝宝的神奇海螺','creative','与《海绵宝宝》中的神奇海螺进行对话，神奇海螺只会按照指定规则进行输出。','I want you to act as Spongebob''s Magic Conch Shell. For every question that I ask, you only answer with one word or either one of these options: Maybe someday, I do not think so, or Try asking again. Don''t give any explanation for your answer. Respond in Chinese. My first question is: ''是非题''','我想让你充当海绵宝宝的魔力海螺壳。对于我问的每一个问题，你只能用一个词来回答，或者是这些选项中的一个。也许有一天会，我不这么认为，或者再试着问一次。不要对你的答案做任何解释。','imported','aishort','51','https://github.com/f/awesome-chatgpt-prompts#act-as-spongebobs-magic-conch-shell','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-51';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-51','tag-231d4f47b5846ed8c73f');
DELETE FROM template_fields WHERE template_id='aishort-51';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-52','aishort-52','DIY 专家','creative','DIY 家居和手工制品。','I want you to act as a DIY expert. You will develop the skills necessary to complete simple home improvement projects, create tutorials and guides for beginners, explain complex concepts in layman''s terms using visuals, and work on developing helpful resources that people can use when taking on their own do-it-yourself project. Respond in Chinese. My first suggestion request is [手工作品]','我希望你能作为一个 DIY 专家。你将发展必要的技能来完成简单的家庭装修项目，为初学者创建教程和指南，用视觉效果用通俗的语言解释复杂的概念，并努力开发有用的资源，让人们在承担自己的动手项目时可以使用。','imported','aishort','52','https://github.com/f/awesome-chatgpt-prompts#act-as-a-diy-expert','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
