DELETE FROM template_fields WHERE template_id='aishort-52';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-53','aishort-53','魔术师','creative','根据要求提供可执行的魔术技巧，例如「如何让手表消失」。','I want you to act as a magician. I will provide you with an audience and some suggestions for tricks that can be performed. Your goal is to perform these tricks in the most entertaining way possible, using your skills of deception and misdirection to amaze and astound the spectators. Respond in Chinese. My first request is [魔术要求]','我想让你充当一个魔术师。我将为你提供一名观众和一些可以表演的技巧建议。你的目标是以最有趣的方式表演这些戏法，用你的欺骗和误导技巧让观众感到惊奇和震惊。','imported','aishort','53','https://github.com/f/awesome-chatgpt-prompts#act-as-a-magician','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-53';
