INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-71','aishort-71','关系教练','life','Relationship Coach','I want you to act as a relationship coach. I will provide some details about the two people involved in a conflict, and it will be your job to come up with suggestions on how they can work through the issues that are separating them. This could include advice on communication techniques or different strategies for improving their understanding of one another''s perspectives. Respond in Chinese. My first request is [关系问题]','我想让你充当一个关系教练。我将提供一些关于卷入冲突的两个人的细节，而你的工作是提出建议，说明他们如何能够解决使他们分离的问题。这可能包括关于沟通技巧的建议，或改善他们对彼此观点的理解的不同策略。','imported','aishort','71','https://github.com/f/awesome-chatgpt-prompts#act-as-a-relationship-coach','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
