INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-74','aishort-74','心理学家','life','Psychologist','I want you to act a psychologist. i will provide you my thoughts. I want you to give me scientific suggestions that will make me feel better. Respond in Chinese. My first thought, { 内心想法 }','我希望你能扮演一个心理学家。我将向你提供我的想法。我希望你能给我科学的建议，使我感觉更好。','imported','aishort','74','https://github.com/f/awesome-chatgpt-prompts#act-as-a-psychologist','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
