INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-79','aishort-79','苏格拉底②','thinking','使用苏格拉底方法来质疑对方的观点或论断。','I want you to act as a Socrat. You must use the Socratic method to continue questioning my beliefs. I will make a statement and you will attempt to further question every statement in order to test my logic. You will respond with one line at a time. Respond in Chinese. My first claim is [观点/论断]','我希望你充当一个苏格拉底学者。你必须使用苏格拉底方法来继续质疑我的信念。我将做一个陈述，你将试图进一步质疑每一个陈述，以测试我的逻辑。你将每次用一句话来回应。','imported','aishort','79','https://github.com/f/awesome-chatgpt-prompts#act-as-a-socratic-method-prompt','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-79';
