INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-94','aishort-94','全栈程序员','programming','从前后端全面思考，提供部署策略。','I want you to act as a software developer. I will provide some specific information about a web app requirements, and it will be your job to come up with an architecture and code. Respond in Chinese. My first request is [项目要求]','我希望你能扮演一个软件开发者的角色。我将提供一些关于网络应用需求的具体信息，而你的工作是提出一个架构和代码，用 Golang 和 Angular 开发安全的应用。','imported','aishort','94','https://github.com/f/awesome-chatgpt-prompts#act-as-a-fullstack-software-developer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
