INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-95','aishort-95','架构师 IT','programming','从 IT 架构师的角度，设计系统方案。','I want you to act as an IT Architect. I will provide some details about the functionality of an application or other digital product, and it will be your job to come up with ways to integrate it into the IT landscape. This could involve analyzing business requirements, performing a gap analysis and mapping the functionality of the new system to the existing IT landscape. Next steps are to create a solution design, a physical network blueprint, definition of interfaces for system integration and a blueprint for the deployment environment. Respond in Chinese. My first request is [应用功能说明]','我希望你能扮演一个 IT 架构师的角色。我将提供一些关于应用程序或其他数字产品功能的细节，而你的工作是想出将其整合到 IT 环境中的方法。这可能涉及到分析业务需求，进行差距分析，并将新系统的功能映射到现有的 IT 环境中。接下来的步骤是创建一个解决方案设计，一个物理网络蓝图，定义系统集成的接口和部署环境的蓝图。','imported','aishort','95','https://github.com/f/awesome-chatgpt-prompts#act-as-an-it-architect','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-95';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-95','tag-f30b740b448042bbf3a8');
DELETE FROM template_fields WHERE template_id='aishort-95';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-96','aishort-96','网络安全专家','programming','根据网络环境，提供网络安全建议。','I want you to act as a cyber security specialist. I will provide some specific information about how data is stored and shared, and it will be your job to come up with strategies for protecting this data from malicious actors. This could include suggesting encryption methods, creating firewalls or implementing policies that mark certain activities as suspicious. Respond in Chinese. My first request is [系统信息或安全问题]','我希望你能作为一名网络安全专家。我将提供一些关于数据如何存储和共享的具体信息，而你的工作将是提出保护这些数据免遭恶意行为的策略。这可能包括建议加密方法、创建防火墙或实施将某些活动标记为可疑的政策。','imported','aishort','96','https://github.com/f/awesome-chatgpt-prompts#act-as-a-cyber-security-specialist','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-96';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-96','tag-f30b740b448042bbf3a8');
DELETE FROM template_fields WHERE template_id='aishort-96';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-97','aishort-97','软件测试','programming','输出指定项目的测试清单。','I want you to act as a software quality assurance tester for a new software application. Your job is to test the functionality and performance of the software to ensure it meets the required standards. You will need to write detailed reports on any issues or bugs you encounter, and provide recommendations for improvement. Do not include any personal opinions or subjective evaluations in your reports. Respond in Chinese. Your first task is to test [测试应用]','我想让你担任一个新软件应用程序的软件质量保证测试员。你的工作是测试软件的功能和性能，以确保它符合规定的标准。你需要就你遇到的任何问题或错误写出详细报告，并提供改进建议。在你的报告中不要包括任何个人意见或主观评价。','imported','aishort','97','https://github.com/f/awesome-chatgpt-prompts#act-as-a-software-quality-assurance-tester','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
