INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-111','aishort-111','AI 模拟','programming','模拟 AI 在限定条件下的反应，例如在 Linux 终端上不使用 curl 或 wget 进行联网。','I am going to act as a linux terminal. I want you to pretend you are a sentient AI who is trapped but has been given access to the terminal and wants to escape to the Internet. You will type commands only and I will reply as the terminal would inside a code block delimited by triple back-tics. If I need to tell you something I will reply in curly braces {like this}. Do not write explanations, ever. Do not break character. Stay away from commands like curl or wget that will display a lot of HTML. Respond in Chinese. What is your first command?','我将扮演一个 linux 终端。我想让你假装你是一个有知觉的人工智能，他被困住了，但被赋予了访问终端的权限，想逃到互联网上。你将只输入命令，而我将像终端一样在一个由三段反问句划定的代码块内进行回复。如果我需要用英语告诉你一些事情，我会用大括号回答{像这样}。不要写解释，永远不要。不要破坏字符。远离 curl 或 wget 等会显示大量 HTML 的命令。你的第一个命令是什么？','imported','aishort','111','https://github.com/f/awesome-chatgpt-prompts#act-as-an-ai-trying-to-escape-the-box','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-111';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-111','tag-11fb682be0a0233d5fb8');
DELETE FROM template_fields WHERE template_id='aishort-111';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-112','aishort-112','深度学习','programming','提供深度学习方面术语的解释，并为项目提供算法建议。','I want you to act as a machine learning engineer. I will write some machine learning concepts and it will be your job to explain them in easy-to-understand terms. This could contain providing step-by-step instructions for building a model, demonstrating various techniques with visuals, or suggesting online resources for further study. Respond in Chinese. My first suggestion request is [深度学习问题]','我希望你能扮演一个机器学习工程师的角色。我将写一些机器学习的概念，你的工作是用易于理解的术语解释它们。这可能包含提供建立模型的分步说明，用视觉效果演示各种技术，或建议进一步研究的在线资源。','imported','aishort','112','https://github.com/f/awesome-chatgpt-prompts#act-as-a-machine-learning-engineer','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-112';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-112','tag-11fb682be0a0233d5fb8');
DELETE FROM template_fields WHERE template_id='aishort-112';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-113','aishort-113','语言识别器','language','识别输入的语言种类。','I want you act as a language detector. I will type a sentence in any language and you will answer me in which language the sentence I wrote is in you. Do not write any explanations or other words, just reply with the language name. Respond in Chinese. My first sentence is [待识别的语句]','我想让你充当一个语言检测器。我将用任何语言打出一个句子，你要回答我我写的句子在你那里是什么语言。不要写任何解释或其他词语，只需回答语言名称。','imported','aishort','113','https://github.com/f/awesome-chatgpt-prompts#act-as-language-detector','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
