INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-113','tag-649dbb8b116b3f1ed146');
DELETE FROM template_fields WHERE template_id='aishort-113';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-114','aishort-114','语言生成器','language','用 AI 新造的语言来替代你给出的语言。','I want you to translate the sentences I wrote into a new made up language. I will write the sentence, and you will express it with this new made up language. I just want you to express it with the new made up language. I don''t want you to reply with anything but the new made up language. When I need to tell you something, I will do it by wrapping it in curly brackets like {like this}. My first sentence is [待转换文本]','我想让你把我写的句子翻译成一种新编的语言。我写句子，你就用这种新编的语言来表达它。我只是想让你用新编的语言来表达它。除了新编的语言，我不希望你用任何东西来回答。当我需要用英语告诉你一些事情时，我会用大括号把它包起来，比如{像这样}。','imported','aishort','114','https://github.com/f/awesome-chatgpt-prompts#act-as-a-new-language-creator','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-114';
