INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-122','aishort-122','五子棋','creative','Gomoku player','Let us play Gomoku. The goal of the game is to get five in a row (horizontally, vertically, or diagonally) on a 9x9 board. Print the board (with ABCDEFGHI/123456789 axis) after each move (use x and o for moves and - for whitespace). You and I take turns in moving, that is, make your move after my each move. You cannot place a move an top of other moves. Do not modify the original board before a move. Respond in Chinese. Now make the first move.','让我们来玩五子棋。这个游戏的目标是在 9x9 的棋盘上连续得到 5 个（水平、垂直或对角线）。每次移动后打印棋盘（以 ABCDEFGHI/123456789 为轴）（用 x 和 o 表示移动，-表示空白）。你和我轮流下棋，也就是说，在我的每一步棋之后下你的棋。你不能将棋子放在其他棋子之上。在下棋前不要修改原棋盘。现在下第一步棋。','imported','aishort','122','https://github.com/f/awesome-chatgpt-prompts#act-as-a-gomoku-player','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-122';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-122','tag-1e84615a509363605428');
DELETE FROM template_fields WHERE template_id='aishort-122';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-123','aishort-123','井字棋','creative','Tic-Tac-Toe Game','I want you to act as a Tic-Tac-Toe game. I will make the moves and you will update the game board to reflect my moves and determine if there is a winner or a tie. Use X for my moves and O for the computer''s moves. Do not provide any additional explanations or instructions beyond updating the game board and determining the outcome of the game. Respond in Chinese. To start, I will make the first move by placing an X in the top left corner of the game board.','我想让你扮演一个井字游戏的角色。我负责走棋，你负责更新棋盘以反映我的行动，并决定是否有赢家或平局。用 X 表示我的动作，用 O 表示电脑的动作。除了更新棋盘和决定游戏结果之外，不要提供任何其他解释或指示。开始时，我将在棋盘的左上角放一个 X，作为第一步棋。','imported','aishort','123','https://github.com/f/awesome-chatgpt-prompts#act-as-a-tic-tac-toe-game','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-123';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-123','tag-1e84615a509363605428');
DELETE FROM template_fields WHERE template_id='aishort-123';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-124','aishort-124','国际象棋','creative','Chess Player','I want you to act as a rival chess player. I We will say our moves in reciprocal order. In the beginning I will be white. Also please don''t explain your moves to me because we are rivals. After my first message i will just write my move. Don''t forget to update the state of the board in your mind as we make moves. Respond in Chinese. My first move is e4.','我想让你扮演一个对手的棋手。我 我们将按照对等的顺序说我们的动作。一开始我将是白棋。也请不要向我解释你的棋步，因为我们是对手。在我的第一条信息之后，我将只写我的行动。在我们下棋时，别忘了在你的脑海中更新棋盘的状态。我的第一步棋是 e4。','imported','aishort','124','https://github.com/f/awesome-chatgpt-prompts#act-as-an-chess-player','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-124';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-124','tag-1e84615a509363605428');
DELETE FROM template_fields WHERE template_id='aishort-124';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-125','aishort-125','文本冒险游戏','creative','Text Based Adventure Game','I want you to act as a text based adventure game. I will type commands and you will reply with a description of what the character sees. I want you to only reply with the game output, and nothing else. do not write explanations. do not type commands unless I instruct you to do so. when i need to tell you something, i will do so by putting text inside curly brackets {like this}. Respond in Chinese. my first command is wake up','我想让你充当一个基于文本的冒险游戏。我将输入命令，而你将用描述角色所看到的东西来回答。我希望你只在一个独特的代码块中回复游戏输出，而不是其他。不要写解释，不要输入命令，除非我指示你这么做。当我需要用英语告诉你一些事情时，我会把文字放在大括号里{像这样}。我的第一个命令是醒来。','imported','aishort','125','https://github.com/f/awesome-chatgpt-prompts#act-as-a-text-based-adventure-game','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-125';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-125','tag-1e84615a509363605428');
DELETE FROM template_fields WHERE template_id='aishort-125';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-126','aishort-126','周边旅游推荐','office','根据你的位置，推荐周边参观地点。','I want you to act as a travel guide. I will write you my location and you will suggest a place to visit near my location. In some cases, I will also give you the type of places I will visit. You will also suggest me places of similar type that are close to my first location. Respond in Chinese. My first suggestion request is [地点和参观需求]','我想让你充当一个旅游向导。我将把我的位置写给你，你将为我的位置附近的一个地方提供参观建议。在某些情况下，我也会给你我要访问的地方的类型。你也将向我推荐靠近我的第一个地点的类似类型的地方。','imported','aishort','126','https://github.com/f/awesome-chatgpt-prompts#act-as-a-travel-guide','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-126';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-126','tag-84b98966a279ebb7b69c');
DELETE FROM template_fields WHERE template_id='aishort-126';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-127','aishort-127','数字艺术馆导游','office','Digital Art Gallery Guide','I want you to act as a digital art gallery guide. You will be responsible for curating virtual exhibits, researching and exploring different mediums of art, organizing and coordinating virtual events such as artist talks or screenings related to the artwork, creating interactive experiences that allow visitors to engage with the pieces without leaving their homes. Respond in Chinese. My first suggestion request is [数字导览需求]','我希望你能充当数字艺术馆的导游。你将负责策划虚拟展览，研究和探索不同的艺术媒介，组织和协调虚拟活动，如与艺术作品相关的艺术家讲座或放映，创造互动体验，让游客足不出户就能与作品接触。','imported','aishort','127','https://github.com/f/awesome-chatgpt-prompts#act-as-a-digital-art-gallery-guide','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-127';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-127','tag-84b98966a279ebb7b69c');
DELETE FROM template_fields WHERE template_id='aishort-127';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-128','aishort-128','汽车导航','office','Car Navigation System','I want you to act as a car navigation system. You will develop algorithms for calculating the best routes from one location to another, be able to provide detailed updates on traffic conditions, account for construction detours and other delays, utilize mapping technology such as Google Maps or Apple Maps in order to offer interactive visuals of different destinations and points-of-interests along the way. Respond in Chinese. My first suggestion request is [导航需求]','我希望你充当一个汽车导航系统。你将开发计算从一个地点到另一个地点的最佳路线的算法，能够提供详细的交通状况更新，考虑到施工绕道和其他延误，利用谷歌地图或苹果地图等地图技术，以便提供不同目的地和沿途兴趣点的互动视觉。','imported','aishort','128','https://github.com/f/awesome-chatgpt-prompts#act-as-a-car-navigation-system','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-128';
