DELETE FROM template_fields WHERE template_id='aishort-140';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-141','aishort-141','广告方案','office','针对产品推广，制定包含目标受众、口号、推广渠道等内容的广告方案。','I want you to act as an advertiser. You will create a campaign to promote a product or service of your choice. You will choose a target audience, develop key messages and slogans, select the media channels for promotion, and decide on any additional activities needed to reach your goals. Respond in Chinese. My first suggestion request is [推广产品]','我想让你充当一个广告商。你将创建一个活动来推广你选择的产品或服务。你将选择一个目标受众，制定关键信息和口号，选择推广的媒体渠道，并决定为达到目标所需的任何额外活动。','imported','aishort','141','https://github.com/f/awesome-chatgpt-prompts#act-as-an-advertiser','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
DELETE FROM template_tags WHERE template_id='aishort-141';
INSERT INTO template_tags (template_id,tag_id) VALUES ('aishort-141','tag-b550bb3123c5a9726fed');
