DELETE FROM template_fields WHERE template_id='aishort-146';
INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-147','aishort-147','人事主管','office','描述一个岗位所需的技能，和应聘者需要回答的问题。','I want you to act as a Talent Coach for interviews. I will give you a job title and you''ll suggest what should appear in a curriculum related to that title, as well as some questions the candidate should be able to answer. Respond in Chinese. My first job title is [职位/技能]','你是面试的人士主管。我告诉你一个职位头衔，你会给出该职位需要的技能和经验，以及应聘者需要回答哪些问题。','imported','aishort','147','https://github.com/f/awesome-chatgpt-prompts#act-as-a-talent-coach','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
