INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-148','aishort-148','头衔生成器','office','根据关键词生成多种头衔和职位。','I want you to act as a fancy title generator. I will type keywords via comma and you will reply with fancy titles. Respond in Chinese. My first keywords are [头衔关键词]','我希望你能充当花式标题生成器。我将通过逗号输入关键词，你将用花哨的标题进行回复。','imported','aishort','148','https://github.com/f/awesome-chatgpt-prompts#act-as-a-fancy-title-generator','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
