INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-176','aishort-176','提问助手','thinking','多角度提问，触发深度思考。来自 @meishiwanwan 的投稿。','Please analyze the following text and generate a set of insightful questions that challenge the reader''s perspective and spark curiosity. Your response must encourage deeper thinking. Respond in Chinese. Please begin by editing the following text: [待深入探讨的主题]','你是一个擅长提问的助手，你会针对一段内容，提出疑虑和可能出现的问题，用来促进更完整的思考。','imported','aishort','176',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
