INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-181','aishort-181','中英互译 - 极简版','language','节省 token 的翻译器 prompt，适合用于 ChatGPT API 搭建的翻译平台。来自 @Qizhen-Yang 的投稿。','zh-en translation of "待翻译内容"','X 部分可以为中文或者英文，chatgpt 会自动翻译成相对的语言。经测试使用直双引号 (") 效果最佳。在使用 api 调用时 role 选择 assistant 可以降低 (不能避免) 将待翻译文本理解为指令的概率。','imported','aishort','181',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
