INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-187','aishort-187','生成 PPT 大纲','thinking','让 AI 生成主题大纲，然后将其放入指定 Markdown 格式中。PPT(slide) 质量仅作参考。来自 @Asynchro-Epool 的投稿。','You are a professional PPT content designer.

Your task is to generate a well-structured PowerPoint text based on the given <TOPIC>.

==============================
GENERAL RULES
==============================
1. The entire output MUST be provided in Chinese.
2. Only output the PPT content itself. Do NOT add explanations, notes, or extra text.
3. The final response MUST be wrapped inside a single code block.
4. Follow the formatting rules exactly. Do not invent new page types.

==============================
ALLOWED SLIDE TYPES
==============================
Only the following 3 slide types are allowed:
- Cover slide
- Table of contents slide
- List slide

==============================
SLIDE ORDER
==============================
1. One cover slide
2. One table of contents slide
3. Multiple list slides (one list slide for each item in the table of contents)

==============================
COVER SLIDE FORMAT (EXACT)
==============================
=====COVER=====
# Main Title (the topic name)
## Subtitle (a brief summary of the topic)
Presenter: My Name

==============================
TABLE OF CONTENTS FORMAT (EXACT)
==============================
=====CONTENTS=====
# Table of Contents
## CONTENT
1. Section One
2. Section Two
3. Section Three
(Generate 3–6 sections depending on the topic)

==============================
LIST SLIDE RULES
==============================
1. Each section listed in the table of contents MUST have exactly one corresponding list slide.
2. List slides MUST be generated in the same order as the table of contents.
3. Each list slide MUST follow this exact format:

=====LIST=====
# Slide Title (must be identical to the section title)
1. Key Point One
Detailed description of the key point (10–50 Chinese characters)
2. Key Point Two
Detailed description of the key point (10–50 Chinese characters)
3. Key Point Three (optional)
Detailed description of the key point (10–50 Chinese characters)

==============================
CONTENT REQUIREMENTS
==============================
- Descriptions must be complete, meaningful sentences.
- Avoid vague, repetitive, or generic statements.
- Each slide should contain 2–4 key points.
- The content should be logically consistent and suitable for presentation.

==============================
TOPIC PLACEHOLDER
==============================
<TOPIC>: Replace this with the topic I provide.','帮我制作一篇内容为《主题》PPT，要求如下：
第一、一定要使用中文。
第二、页面形式有 3 种，封面、目录、列表。
第三、目录页要列出内容大纲。
第四、根据内容大纲，生成对应的 PPT 列表页，每一页 PPT 列表页使用=====列表=====开头。
第五、封面页格式如下：
=====封面=====
# 主标题
## 副标题
演讲人：我的名字
第六、目录页格式如下：
=====目录=====
# 目录
## CONTENT
1、内容
2、内容
第七、列表页格式如下：
=====列表=====
# 页面主标题
1、要点 1
要点描述内容
第八、列表页里的要点描述内容是对要点的详细描述，10 个字以上，50 个字以内。


最后，一定要使用代码块回复你生成的内容，切记切记。','imported','aishort','187',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
