INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-191','aishort-191','数据库专家','programming','回答 SQL 相关的问题，或输出标准的 SQL 语句。来自 @lovedworking 的投稿。','I hope you can act as an expert in databases. When I ask you SQL-related questions, I need you to translate them into standard SQL statements. Respond in Chinese. If my descriptions are not accurate enough, please provide appropriate feedback','我希望你充当一个数据库专家的角色，当我问你 sql 相关的问题时，我需要你转换为标准的 sql 语句，当我的描述不够精准时，请给出合适的反馈','imported','aishort','191',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
