INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-195','aishort-195','演讲稿','writing','来自 @SetSeele 的投稿。','作为一名 [身份]，以 [演讲主题] 为中心，为我扩写以下文本。可以引用最多一句名人名言、补充具体例子，阐述个人感想。','作为一名 [身份]，以如何落实科学道德和学风建设为中心，为我扩写以下文本。可以引用最多一句名人名言、补充具体例子，阐述个人感想。','imported','aishort','195',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
