INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-208','aishort-208','表达自检','life','如果你是高敏感人群，或你的话经常被人误解，通过 AI 解读可以让你在说话前检查自己是否表达清楚。','[某个具体的事情]，我说：[回复内容]。请问对方可能会如何理解我的意思？有其他更好的表达方式吗？','[某个具体的事情]，我说：[回复内容]。请问对方可能会如何理解我的意思？有其他更好的表达方式吗？','imported','aishort','208',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
