INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-214','aishort-214','调研报告助手','writing','根据更换不同的类型，以产出适合自己需求的调研报告。来自 @b3ue 的投稿。','Please write a research report on a topic of [主题]. Ensure that your report includes the following features:

1. A clear problem statement and research objective;
2. A comprehensive analysis and review of existing literature and data;
3. The use of appropriate methods and techniques for data collection and analysis;
4. Accurate conclusions and recommendations to answer the research question and address the research objective.

Respond in Chinese. Please keep the report concise and well-structured, using relevant examples to illustrate your points.','请根据以下提示撰写一份【报告主题】调研报告。您可以根据您的研究领域自由发挥，但请确保您的报告具有以下特征：1. 具有明确的问题陈述和研究目的；2. 包含对现有文献和数据的全面分析和综述；3. 采用适当的方法和技术进行数据收集和分析；4. 提供准确的结论和建议，以回答研究问题并解决研究目的。','imported','aishort','214',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
