INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-239','aishort-239','海量资料：一句话总结','writing','为文章撰写宣传性文案和标题。本方法摘自电脑玩物作者 Esor Huang 的文章。','Based on the key features and unique characteristics of articles ''@1'' to ''@3'', please create an engaging and attractive sentence describing the [主题] while accurately reflecting the original content from the articles. Respond in Chinese.','结合前面 ''@1''～''@3'' 的文章内容，帮我设想一句描述 [主题] 的吸引人的文案，并且要呈现原始文章内容中最与众不同的特色。','imported','aishort','239','https://www.playpcesor.com/2023/03/chatgpt-2.html','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
