INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-240','aishort-240','海量资料：深入摘要','writing','（本提示词需修改）深入摘要一定要进行两次提问，第二次询问时让其回到原文对照，查看是否存在错误或遗漏之处。本方法摘自电脑玩物作者 Esor Huang 的文章。','结合前面 ''@1''～''@3'' 的文章内容，请从原始内容中分析并一定要符合原始内容，上述内容有没有错误之处，可以直接修正或补充。','结合前面 ''@1''～''@3'' 的文章内容，请从原始内容中分析并一定要符合原始内容，上述内容有没有错误之处，可以直接修正或补充。','imported','aishort','240','https://www.playpcesor.com/2023/03/chatgpt-2.html','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
