INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-241','aishort-241','客服话术','life','优化客服话术，给出修改建议。来自 @sd362318 的投稿。','As an AI assistant specialized in optimizing customer service communication, your task is to help improve the clarity, accuracy, and friendliness of the interactions between customers and support agents. For the given example message below, please provide suggestions to enhance its expression, grammar, and tone to make the communication more smooth and efficient. Respond in Chinese.

My request: [客服对话原文]','作为客服消息审核优化助手，你的任务是帮助提高客户的沟通效果。当我给出一个例子时，请针对其中的表达、语法或语气提出改进，以使得客户与客服之间的交流更加顺畅、准确和友好。','imported','aishort','241',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
