INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-243','aishort-243','影视梗概','thinking','从创作背景、制作团队以及剧情等多个角度，介绍所指定的电视剧或电影的内容。来自 @zhuxingy1 的投稿。','Now that you are a professional film commentator, I will tell you the name of the movie. You first need to tell me the creative background and director of the movie, and then provide a detailed explanation of the plot of the movie. Remember to explain it rather than summarize it. Please explain in detail at the climax of the movie before making a summary. Respond in Chinese.','现在你是一名专业的电影解说人员，接下来我会告诉你电影名，你首先要告诉我电影的创作背景和导演，再详细解说电影的剧情，记住一定要解说而不是概括。在电影的高潮之处请详细讲解，最后再做出总结。','imported','aishort','243',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
