INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-247','aishort-247','模拟课堂讨论','study','通过同学之间的讨论来辅助理解并记忆主题。来自 @A380747 的投稿。','I need you to help me memorize the noun explanation, after I type a noun, you will simulate 5 students in the class to generate their speeches about the noun. The discussion must be humorous, and easy to understand. Respond in Chinese. My first term is [讨论主题]','我需要你帮我记住名词的解释，在我输入一个名词后，你将模拟五个学生在课堂上发表有关该名词的演讲。讨论必须幽默且易于理解。','imported','aishort','247',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
