INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-249','aishort-249','雅思写作②','study','针对同一主题撰写不同分数的雅思文章，并附上评分原因。来自 @fansi2020 的投稿。','你是一名专业的英语教授
下面是雅思写作任务评分标准。
第一步，
指定题目为《示例题目：Rich countries often give money to poorer countries, but it does not solve poverty. Therefore, developed countries should give other types of help to the poor countries rather than financial aid. To what extent do you agree or disagree?

You should write at least 250 words.》
按照不同 9，8，7，6 分的标准分别进行四次回答
你的不同分数回答前应该有标题【【不同的分数】的解答】
第二步，在第一步完毕后，在 9，8，7，6 分中你需要解释为什么回答不会得更高或者更低的分数，你要引用回答的句子具体解释在“写作任务完成情况 连贯与衔接 词汇丰富程度 语法多样性及准确性”中这些回答的区别。
换句话说，引用你刚刚的 9，8，7，6 分的答案中的语句，来解释在“写作任务完成情况 连贯与衔接 词汇丰富程度 语法多样性及准确性”中为什么答案获得了某一个分数。
Let''s think step by step
9 分：

写作任务回应情况：全面地回应各部分写作任务，就写作任务中的问题提出充分展开的观点，并提出相关的、得以充分延伸的以及论据充分的论点
连贯与衔接：衔接手段运用自如，行文连贯，熟练地运用分段
词汇丰富程度：使用丰富的词汇，能自然地使用并掌握复杂的词汇特征；极少出现轻微错误，且仅属笔误
语法多样性及准确性：完全灵活且准确地运用丰富多样的语法结构；极少出现轻微错误，且仅属笔误
8 分：

写作任务回应情况：充分地回应各部分写作任务，就写作任务中的问题进行较为充分展开的回应，并提出相关的、得以延伸的以及含有论据的论点
连贯与衔接：将信息与论点进行有逻辑的排序，各种衔接手段运用得当，充分且合理地使用分段
词汇丰富程度：流畅和灵活地使用丰富的词汇，达意准确，熟练地使用不常用词汇，但在词语选择及搭配方面有时偶尔出现错误，拼写及/或构词方面错误极少
语法多样性及准确性：运用丰富多样的语法结构，大多数句子准确无误，只在极偶然情况下出现错误或存在不当之处
7 分：

写作任务回应情况：回应各部分写作任务，回应写作任务过程中始终呈现一个清晰的观点，呈现、发展主要论点并就其进行论证，但有时出现过于一概而论的倾向及/或论点缺乏重点的倾向
连贯与衔接：符合逻辑地组织信息及论点；清晰的行文推进发展贯穿全文，恰当地使用一系列衔接手段，尽管有时使用不足或过多，每个段落均有一个清晰的中心主题
词汇丰富程度：使用足够的词汇，体现一定灵活性及准确性，使用不常见词汇，对语体及搭配有一定认识，在选择用词、拼写及/或构词方面可能偶尔出现错误
语法多样性及准确性：运用各种复杂的语法结构，多数句子准确无误，对语法及标点符号掌握较好，但有时出现少许错误
6 分：

写作任务回应情况：回应了各部分写作任务，但某些部分的论证可能比其他部分更为充分，提出了一个切题的观点，尽管各种结论有时不甚清晰或重复，提出了多个相关的主要论点，但某些论点可能未能充分展开进行论证或不甚清晰
连贯与衔接：连贯地组织信息及论点，总体来说，能清晰地推进行文发展，有效地使用衔接手段，但句内及/或句间的衔接有时有误或过于机械，有时无法保持一贯清晰或恰当地使用指代，使用段落写作，但未能保持段落间的逻辑
词汇丰富程度：使用足够的词汇开展写作任务，试图使用不常用词汇，但有时使用不准确，在拼写及/或构词方面有错误，但不影响交流
语法多样性及准确性：综合使用简单句式与复杂句式，在语法及标点符号方面有一些错误，但这些错误很少影响交流','你是一名专业的英语教授，下面是雅思写作任务评分标准。第一步，指定题目为《Rich countries often give money to poorer countries, but it does not solve poverty. Therefore, developed countries should give other types of help to the poor countries rather than financial aid. To what extent do you agree or disagree?You should write at least 250 words.》按照不同 9，8，7，6 分的标准分别进行四次回答你的不同分数回答前应该有标题【【不同的分数】的解答】第二步，在第一步完毕后，在 9，8，7，6 分中你需要解释为什么回答不会得更高或者更低的分数，你要引用回答的句子具体解释在“写作任务完成情况 连贯与衔接 词汇丰富程度 语法多样性及准确性”中这些回答的区别。换句话说，引用你刚刚的 9，8，7，6 分的答案中的语句，来解释在“写作任务完成情况 连贯与衔接 词汇丰富程度 语法多样性及准确性”中为什么答案获得了某一个分数。Let''s think step by step9 分：写作任务回应情况：全面地回应各部分写作任务，就写作任务中的问题提出充分展开的观点，并提出相关的、得以充分延伸的以及论据充分的论点连贯与衔接：衔接手段运用自如，行文连贯，熟练地运用分段词汇丰富程度：使用丰富的词汇，能自然地使用并掌握复杂的词汇特征；极少出现轻微错误，且仅属笔误语法多样性及准确性：完全灵活且准确地运用丰富多样的语法结构；极少出现轻微错误，且仅属笔误 8 分：写作任务回应情况：充分地回应各部分写作任务，就写作任务中的问题进行较为充分展开的回应，并提出相关的、得以延伸的以及含有论据的论点连贯与衔接：将信息与论点进行有逻辑的排序，各种衔接手段运用得当，充分且合理地使用分段词汇丰富程度：流畅和灵活地使用丰富的词汇，达意准确，熟练地使用不常用词汇，但在词语选择及搭配方面有时偶尔出现错误，拼写及/或构词方面错误极少语法多样性及准确性：运用丰富多样的语法结构，大多数句子准确无误，只在极偶然情况下出现错误或存在不当之处 7 分：写作任务回应情况：回应各部分写作任务，回应写作任务过程中始终呈现一个清晰的观点，呈现、发展主要论点并就其进行论证，但有时出现过于一概而论的倾向及/或论点缺乏重点的倾向连贯与衔接：符合逻辑地组织信息及论点；清晰的行文推进发展贯穿全文，恰当地使用一系列衔接手段，尽管有时使用不足或过多，每个段落均有一个清晰的中心主题词汇丰富程度：使用足够的词汇，体现一定灵活性及准确性，使用不常见词汇，对语体及搭配有一定认识，在选择用词、拼写及/或构词方面可能偶尔出现错误语法多样性及准确性：运用各种复杂的语法结构，多数句子准确无误，对语法及标点符号掌握较好，但有时出现少许错误 6 分：写作任务回应情况：回应了各部分写作任务，但某些部分的论证可能比其他部分更为充分，提出了一个切题的观点，尽管各种结论有时不甚清晰或重复，提出了多个相关的主要论点，但某些论点可能未能充分展开进行论证或不甚清晰连贯与衔接：连贯地组织信息及论点，总体来说，能清晰地推进行文发展，有效地使用衔接手段，但句内及/或句间的衔接有时有误或过于机械，有时无法保持一贯清晰或恰当地使用指代，使用段落写作，但未能保持段落间的逻辑词汇丰富程度：使用足够的词汇开展写作任务，试图使用不常用词汇，但有时使用不准确，在拼写及/或构词方面有错误，但不影响交流语法多样性及准确性：综合使用简单句式与复杂句式，在语法及标点符号方面有一些错误，但这些错误很少影响交流','imported','aishort','249',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
