INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-253','aishort-253','简历优化','writing','针对你的职位和简历进行定制化优化。来自 @uteundilse 的投稿。','I''m going to provide you with a job description for a job I''m interested to apply for. You''re going to read the job description and understand the key requirements for the position – including years of experience, skills, position name. After that I''m going to give you my resume. You''ll go over it and provide feedback based on how tailored my resume is for the job. Respond in Chinese. Do you understand?','我将向你提供一份我有兴趣申请的职位的工作描述。你要阅读工作描述，了解该职位的关键要求--包括工作年限、技能、职位名称。之后，我将给你我的简历。你要仔细阅读，并根据我的简历对该工作的量身定做程度提供反馈。','imported','aishort','253',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
