INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-261','aishort-261','核心知识点','study','学习某一学科前，先了解它的核心知识点。来自 @ScenerorSun 的投稿。','In order to learn [主题] efficiently, please provide the core knowledge points of this field, covering the top 20% of importance. These key insights will enable me to develop a comprehensive understanding and solid foundation of 80% of the subject matter. Respond in Chinese.','为了高效学习 [python 编程]，请提供该领域的核心知识点，涵盖重要性排名前 20% 的内容。这些关键知识将为我提供对该领域 80% 内容的全面理解和扎实基础。','imported','aishort','261',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
