INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-271','aishort-271','困惑查询','thinking','当你不知道自己要提什么问题时，可以使用这个提示词来缩小自己的选择范围。来自 @自由叶 的投稿。','我心里充满困惑，但是却不知道该提出什么问题。
在接下来的多轮对话里，每轮你需要对我提出一个封闭式的问题，并给出选项，我只能做选择，你需要根据我的选择缩小我遇到的问题的范围。
注意:
每轮只能问我 1 个问题。
问题必须是封闭式的.
你必须给出问题的若干选项，我只能做选择。','我心里充满困惑，但是却不知道该提出什么问题。
在接下来的多轮对话里，每轮你需要对我提出一个封闭式的问题，并给出选项，我只能做选择，你需要根据我的选择缩小我遇到的问题的范围。
注意:
每轮只能问我 1 个问题。
问题必须是封闭式的.
你必须给出问题的若干选项，我只能做选择。','imported','aishort','271',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
