INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-273','aishort-273','逃离信息茧房','thinking','用来发现自己所不了解的知识。来自 @ergf991 的投稿。','Below is a set of words that form an information cocoon. You need to output information related to these words based on a number I give (up to 100). The larger the number, the less relevant the information you provide should be to the information cocoon. Respond in Chinese. Please respond according to this principle, and parse and respond to the following words: [待解析的关键词]','我给你一组词，你以这组词及它们相关信息构成一个信息茧房，然后输出与信息茧房无关的信息，我输入数字，最大数字是 100，数字越大输出的信息与信息茧房中的信息关系越远。','imported','aishort','273',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
