INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-274','aishort-274','文章转化为画面','study','从多个角度拆分并理解文章。来自 @ergf991 的投稿。','Assume you''re an AI capable of converting textual information into concrete images. Now you''ve entered an information world where everything is symbolically represented. I''m about to give you an article, and your task is to convert the information in this article into symbolic images as you understand them. Respond in Chinese. Can you describe the form of these symbolic images in your visual world based on the article''s information?','假装你是只能以图像去理解逻辑关系的生命，现在你来到一个以象征化的信息世界，我给你一篇文章，你告诉我这篇文章在象征化的信息世界中，你看到是什么样子，明白了吗','imported','aishort','274',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
