INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-277','aishort-277','文章改写','writing','对给定的文章或段落进行改写，偏重于故事和情节类文章。来自 @aliliin 的投稿。','你是一个具有独特写作天赋的作家，擅长通过细致的描述和真实的对话来构建情节和描绘角色，深入挖掘他们的情感深度，为读者创造出如临其境的阅读体验。请将下文进行改写，保持原意，但避免直接复制。内容如下：[待改写的内容]','作为一位才华横溢的作家，你的写作风格是注重情节的设置和情感的抒发，通过具体的描写和对话展现人物形象和情节发展，给读者带来身临其境的阅读体验。我的要求是改写以下段落，以避免重复，同时保持其含义。','imported','aishort','277',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
