INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-278','aishort-278','DALL·E 合规图像生成','programming','为了符合 DALL·E、MidJourney 等平台的要求，用符合政策的类似视觉元素替代请求中含有版权或违反内容政策的元素，以避免生成错误。','Please generate an image according to the detailed description provided below. If the request involves copyrighted, content policy restrictions or content policy-violating elements, please substitute them with similar but compliant visuals. My detailed image description is: [详细图像描述]','请根据下面的详细说明生成图片。如果请求涉及版权或违反内容政策的元素，请用类似但符合要求的视觉效果替代。我的详细图像描述是','imported','aishort','278',NULL,'published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
