INSERT INTO templates (id,slug,title,category_id,description,content,translation,kind,source_id,source_record_id,source_url,status,version) VALUES ('aishort-279','aishort-279','AI 工作流诊断','office','适合内容创作者、课程老师、顾问和小团队梳理第一个可复用 AI 工作流。来自 @Ronnie2025 的投稿。','我希望你担任 AI 工作流诊断顾问。我会提供一个反复出现的任务、已有素材、目标用户、输出格式和当前卡点。请先判断这个任务是否值得做成可复用工作流，然后按以下结构输出：

1. 任务边界：这个工作流解决什么问题，不解决什么问题。
2. 输入字段：每次使用前必须填写哪些信息。
3. 处理步骤：AI 应该按什么顺序完成任务。
4. 输出格式：最终结果用什么结构交付。
5. 质检清单：用哪些标准检查结果是否可用。
6. 迭代记录：下次如何根据反馈改进提示词。

如果关键信息缺失，请先问不超过 5 个问题；如果信息足够，请直接输出工作流方案。不要编造我没有提供的事实。

我的第一个任务是：[例如：每周把一篇长文整理成小红书图文草稿]','把反复出现的任务拆成边界、输入、步骤、输出格式、质检清单和迭代记录，适合把一次性提示词整理成可复用工作流。','imported','aishort','279','https://github.com/Ronnie2025/ai-workflow-prompts-zh','published',1) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,category_id=excluded.category_id,description=excluded.description,content=excluded.content,translation=excluded.translation,kind=excluded.kind,source_id=excluded.source_id,source_record_id=excluded.source_record_id,source_url=excluded.source_url,status=excluded.status,version=excluded.version;
